'use strict';
(()=>{const KEY='gp-nutrition-v2-ergonomic-prototype-only', $=id=>document.getElementById(id), today=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')},fmt=(n,d=1)=>Number(n).toLocaleString('fr-FR',{maximumFractionDigits:d}),safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\'':'&#39;'}[c]));
const KINDS=[['waist','Taille'],['hips','Hanches'],['glutes','Fessiers'],['thigh','Cuisse'],['chest','Poitrine'],['upperThigh','Haut de cuisse'],['arm','Bras']];
const DEMO=new URLSearchParams(location.search).get('demo')==='1';
const demoDates=Array.from({length:9},(_,i)=>{const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()-28+i*3.5);return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')});
const demoWeights=[74.5,74.2,74.1,73.8,73.6,73.4,73.2,73.1,72.8];
const demoWaist=[85,84.7,84.3,84,83.5,83.2,82.8,82.4,82];
const demoGlutes=[108,108.1,108.3,108.5,108.6,108.8,109,109.1,109.3];
const demoData={weights:Object.fromEntries(demoDates.map((d,i)=>[d,demoWeights[i]])),measurements:Object.fromEntries(demoDates.map((d,i)=>[d,{waist:demoWaist[i],hips:101-i*.2,glutes:demoGlutes[i],thigh:56+i*.08,chest:97,upperThigh:65,arm:29+i*.04}]))};
const read=()=>{try{const real=JSON.parse(localStorage.getItem(KEY))||{};return DEMO?{...real,weights:demoData.weights,measurements:demoData.measurements}:real}catch{return DEMO?demoData:{}}},write=db=>{if(DEMO)return;localStorage.setItem(KEY,JSON.stringify(db));};
if(DEMO){const banner=document.createElement('div');banner.className='tracking-demo-banner';banner.innerHTML='<strong>🧪 Démonstration : données fictives</strong><span>9 relevés de poids et de mensurations sur 30 jours. Tes données réelles ne sont pas modifiées.</span><a href="'+location.pathname+'#suivi">Quitter la démonstration</a>';document.getElementById('tracking-dashboard').prepend(banner);document.querySelectorAll('[data-quick], [data-delete-weight], [data-delete-measure]').forEach(b=>b.disabled=true);}

const dayOffset=(date,n)=>{const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+n);return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')};
const avg=values=>values.length?values.reduce((a,b)=>a+b,0)/values.length:null;
const stat=(label,value)=>'<div class="track-stat"><b>'+value+'</b><small>'+label+'</small></div>';
const diff=(a,b,unit)=>a==null||b==null?'—':(b-a>0?'+':'')+fmt(b-a)+' '+unit;
function chart(target,title,entries,unit){const el=$(target);if(!entries.length){el.innerHTML='<div class="track-chart"><h3>'+title+'</h3><p class="chart-note">Pas encore de données pour ce graphique.</p></div>';return;}const w=320,h=160,pad=28,values=entries.map(x=>x.value),min=Math.min(...values),max=Math.max(...values),spread=Math.max(max-min,1),x=i=>pad+(w-2*pad)*(entries.length===1?.5:i/(entries.length-1)),y=v=>h-pad-(v-min)/spread*(h-2*pad);const coords=entries.map((e,i)=>x(i)+','+y(e.value)).join(' ');const points=entries.map((e,i)=>'<circle cx="'+x(i)+'" cy="'+y(e.value)+'" r="3" fill="#f7c27e"><title>'+safe(e.date)+' : '+fmt(e.value)+' '+unit+'</title></circle>').join('');el.innerHTML='<div class="track-chart"><h3>'+title+'</h3><svg viewBox="0 0 320 160" role="img" aria-label="'+safe(title)+'"><line x1="28" y1="132" x2="292" y2="132" stroke="#6b8176"/><polyline points="'+coords+'" fill="none" stroke="#55d4b3" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>'+points+'<text x="2" y="20" font-size="11" fill="#e6d9b8">'+fmt(max)+' '+unit+'</text><text x="2" y="151" font-size="11" fill="#e6d9b8">'+fmt(min)+'</text></svg><p class="chart-note">'+entries.length+' relevé(s), du '+safe(entries[0].date)+' au '+safe(entries[entries.length-1].date)+'</p></div>';}
function period(id){const mode=$(id+"-window").value,custom=mode==="custom";$(id+"-custom").hidden=!custom;const end=custom?$(id+"-to").value:today(),start=custom?$(id+"-from").value:dayOffset(end,1-Number(mode));const valid=!!start&&!!end&&start<=end;$(id+"-period-error").hidden=valid;$(id+"-period-error").textContent="Choisis une date de début antérieure ou égale à la date de fin.";return {start,end,valid};}
function renderWeight(){const db=read(),list=Object.entries(db.weights||{}).filter(([date,v])=>/^\d{4}-\d{2}-\d{2}$/.test(date)&&Number.isFinite(Number(v))&&Number(v)>0).sort((a,b)=>a[0].localeCompare(b[0])).map(([date,v])=>({date,value:Number(v)})),range=period('weight'),visible=list.filter(e=>range.valid&&e.date>=range.start&&e.date<=range.end),last=visible.at(-1),previous=visible.at(-2);const latest=list.at(-1);$('weight-last').textContent=latest?fmt(latest.value)+' kg':'— kg';$('weight-last-date').textContent=latest?'Le '+displayDate(latest.date):'Aucune pesée';$('weight-average').textContent=visible.length?fmt(avg(visible.map(e=>e.value)))+' kg':'—';$('weight-difference').textContent=last&&previous?'Depuis la précédente : '+diff(previous.value,last.value,'kg'):visible.length+' pesée(s) sur la période';document.querySelectorAll('[data-weight-period]').forEach(b=>{const active=b.dataset.weightPeriod===$('weight-window').value;b.setAttribute('aria-pressed',String(active));});chart('weight-chart','Évolution du poids',visible,'kg');$('weight-history').innerHTML=visible.slice().reverse().map(e=>'<div class="track-entry"><span>'+e.date+' · '+fmt(e.value)+' kg</span><button data-delete-weight="'+e.date+'">Supprimer</button></div>').join('')||'<p class="tracking-note">Aucune pesée enregistrée.</p>';}
function renderCombined(range){const db=read(),sources=[['combine-weight','Poids',db.weights||{},'#58d9a6'],['combine-waist','Taille',Object.fromEntries(Object.entries(db.measurements||{}).map(([d,v])=>[d,v.waist])),'#f8c078'],['combine-glutes','Fessiers',Object.fromEntries(Object.entries(db.measurements||{}).map(([d,v])=>[d,v.glutes])),'#e67c88']];const selected=sources.filter(([id])=>$(id).checked).map(([id,name,records,color])=>({name,color,entries:Object.entries(records).filter(([date,v])=>range.valid&&date>=range.start&&date<=range.end&&v!=null&&Number(v)>0).sort((a,b)=>a[0].localeCompare(b[0]))})).filter(s=>s.entries.length);if(!selected.length){$('combined-chart').innerHTML='<div class="track-chart"><h3>Courbes combinées</h3><p class="chart-note">Sélectionne une mesure et enregistre des relevés pour afficher les courbes.</p></div>';return;}const dates=[...new Set(selected.flatMap(s=>s.entries.map(e=>e[0])))].sort(),w=320,h=170,pad=30,x=date=>pad+(w-2*pad)*(dates.length===1?.5:dates.indexOf(date)/(dates.length-1));const lines=selected.map(s=>{const values=s.entries.map(e=>Number(e[1])),min=Math.min(...values),max=Math.max(...values),span=Math.max(max-min,.1),y=v=>h-pad-(v-min)/span*(h-2*pad);return '<polyline fill="none" stroke="'+s.color+'" stroke-width="3" points="'+s.entries.map(([d,v])=>x(d)+','+y(Number(v))).join(' ')+'"/>'+s.entries.map(([d,v])=>'<circle cx="'+x(d)+'" cy="'+y(Number(v))+'" r="3" fill="'+s.color+'"><title>'+s.name+' '+d+' : '+fmt(v)+'</title></circle>').join('')});$('combined-chart').innerHTML='<div class="track-chart"><h3>Courbes combinées — évolution relative</h3><svg viewBox="0 0 320 170" role="img" aria-label="Évolution combinée du poids et des mensurations">'+lines.join('')+'</svg><p class="chart-note">Chaque courbe utilise sa propre échelle. Comparer les tendances, pas les hauteurs entre courbes.</p></div>';}
function renderMeasure(){const db=read(),kind=$('measure-kind').value,list=Object.entries(db.measurements||{}).filter(([date,record])=>record&&Number.isFinite(Number(record[kind]))&&Number(record[kind])>0).sort((a,b)=>a[0].localeCompare(b[0])).map(([date,record])=>({date,value:Number(record[kind])}));const range=period('measure'),visible=list.filter(e=>range.valid&&e.date>=range.start&&e.date<=range.end),latest=list.at(-1);$('measure-last').textContent=latest?fmt(latest.value)+' cm':'— cm';$('measure-last-date').textContent=latest?'Le '+displayDate(latest.date):'Aucune mesure pour cette zone';$('measure-average').textContent=visible.length?fmt(avg(visible.map(e=>e.value)))+' cm':'—';$('measure-difference').textContent=visible.length>1?'Évolution : '+diff(visible[0].value,visible.at(-1).value,'cm'):visible.length+' relevé(s) sur la période';document.querySelectorAll('[data-measure-period]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.measurePeriod===$('measure-window').value)));chart('measure-chart','Évolution : '+KINDS.find(x=>x[0]===kind)[1],visible,'cm');renderCombined(range);const from=$('measure-compare-from').value,to=$('measure-compare-to').value,a=(db.measurements||{})[from]?.[kind],b=(db.measurements||{})[to]?.[kind];$('measure-compare').innerHTML=stat('Date de départ',a?fmt(a)+' cm':'—')+stat('Date de fin',b?fmt(b)+' cm':'—')+stat('Évolution',diff(a==null?null:Number(a),b==null?null:Number(b),'cm'));$('measure-history').innerHTML=visible.slice().reverse().map(e=>'<div class="track-entry"><span>'+displayDate(e.date)+' · '+fmt(e.value)+' cm</span><button data-delete-measure="'+e.date+'">Supprimer</button></div>').join('')||'<p class="tracking-note">Aucune mesure pour cette zone.</p>';}
function nutritionTotals(items){return(items||[]).reduce((a,i)=>{const q=Number(i.grams)/100;for(const k of ['kcal','p','c','f'])a[k]+=Number(i[k]||0)*q;return a},{kcal:0,p:0,c:0,f:0})}
function renderNutrition(){const db=read(),mode=$('nutrition-window').value,custom=mode==='custom';$('nutrition-custom').hidden=!custom;const end=custom?$('nutrition-to').value:today(),start=custom?$('nutrition-from').value:dayOffset(end,1-Number(mode));const valid=!!start&&!!end&&start<=end;const count=valid?Math.round((new Date(end+'T12:00:00')-new Date(start+'T12:00:00'))/86400000)+1:0;$('nutrition-period-error').hidden=valid;$('nutrition-period-error').textContent='Choisis une date de début antérieure ou égale à la date de fin.';const entries=Object.entries(db.days||{}).filter(([date,r])=>valid&&date>=start&&date<=end&&r.complete===true).sort((a,b)=>a[0].localeCompare(b[0])).map(([date,r])=>({date,...nutritionTotals(r.items)}));const selectedDate=$('day')?.value||today(),record=db.days?.[selectedDate],items=Array.isArray(record?.items)?record.items:[],totals=nutritionTotals(items);$('nutrition-last').textContent=fmt(totals.kcal)+' kcal';$('nutrition-last-date').textContent=displayDate(selectedDate)+(record?.complete?' · Journée complète':items.length?' · En cours':' · Aucun aliment saisi');$('nutrition-last-p').textContent='Protéines '+fmt(totals.p)+' g';$('nutrition-last-c').textContent='Glucides '+fmt(totals.c)+' g';$('nutrition-last-f').textContent='Lipides '+fmt(totals.f)+' g';$('nutrition-average').textContent=entries.length?fmt(avg(entries.map(e=>e.kcal)))+' kcal':'—';$('nutrition-complete-count').textContent=entries.length+' / '+count+' journées complètes';document.querySelectorAll('[data-nutrition-period]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.nutritionPeriod===mode)));$('nutrition-summary').innerHTML=stat('Journées complètes',entries.length+' / '+count)+[['kcal','Calories','kcal'],['p','Protéines','g'],['c','Glucides','g'],['f','Lipides','g']].map(([k,label,unit])=>stat('Moyenne '+label,entries.length?fmt(avg(entries.map(e=>e[k])))+' '+unit:'—')).join('');chart('nutrition-chart','Calories journalières (jours complets)',entries.map(e=>({date:e.date,value:e.kcal})),'kcal');$('nutrition-history').innerHTML=entries.slice().reverse().map(e=>'<div class="track-entry"><span>'+displayDate(e.date)+' · '+fmt(e.kcal)+' kcal · '+fmt(e.p)+' g prot.</span></div>').join('')||'<p class="tracking-note">Aucune journée complète sur cette période.</p>';}
function displayDate(date){if(!date)return '';const [y,m,d]=date.split('-');return d+'/'+m+'/'+y;}
function renderOverview(){const db=read(),weights=Object.entries(db.weights||{}).filter(([d,v])=>/^\d{4}-\d{2}-\d{2}$/.test(d)&&Number(v)>0).sort((a,b)=>a[0].localeCompare(b[0])),lastW=weights.at(-1);$('overview-weight').textContent=lastW?fmt(lastW[1])+' kg':'— kg';$('overview-weight-date').textContent=lastW?'Le '+displayDate(lastW[0]):'Aucune pesée enregistrée';
const measures=Object.entries(db.measurements||{}).filter(([date,record])=>/^\d{4}-\d{2}-\d{2}$/.test(date)&&record&&KINDS.some(([key])=>Number(record[key])>0)).sort((a,b)=>a[0].localeCompare(b[0])),lastM=measures.at(-1);$('overview-measures').innerHTML=lastM?KINDS.filter(([key])=>Number(lastM[1][key])>0).map(([key,label])=>'<span>'+safe(label)+' <b>'+fmt(lastM[1][key])+' cm</b></span>').join(''):'<span>Aucune mensuration enregistrée</span>';$('overview-measures-date').textContent=lastM?'Relevé du '+displayDate(lastM[0]):'';
const selectedDate=$('day')?.value||today(),record=db.days?.[selectedDate],items=Array.isArray(record?.items)?record.items:[],totals=nutritionTotals(items);$('overview-calories').textContent=fmt(totals.kcal)+' kcal';$('overview-protein').textContent='Protéines '+fmt(totals.p)+' g';$('overview-carbs').textContent='Glucides '+fmt(totals.c)+' g';$('overview-fat').textContent='Lipides '+fmt(totals.f)+' g';$('overview-nutrition-date').textContent='Le '+displayDate(selectedDate)+(record?.complete?' · Journée complète':items.length?' · Journée en cours':' · Aucun aliment saisi');}

function render(){renderWeight();renderMeasure();renderNutrition();renderOverview();}
window.addEventListener('gp:nutrition-updated',()=>{renderOverview();renderNutrition();});
for(const id of ['weight','measure']){$(id+'-from').value=dayOffset(today(),-29);$(id+'-to').value=today();$(id+'-window').addEventListener('change',render);$(id+'-from').addEventListener('change',render);$(id+'-to').addEventListener('change',render);} $('measure-compare-from').value=dayOffset(today(),-30);$('measure-compare-to').value=today();$('measure-kind').innerHTML=KINDS.map(([key,label])=>'<option value="'+key+'">'+label+'</option>').join('');
let quickMode='weight';const quickDialog=$('quick-track-dialog');$('quick-track-measures-fields').innerHTML=KINDS.map(([key,label])=>'<label>'+label+' (cm)<input type="number" data-quick-measure="'+key+'" min="1" max="300" step="0.1" inputmode="decimal" placeholder="—"></label>').join('');document.querySelectorAll('[data-quick]').forEach(b=>b.addEventListener('click',()=>{quickMode=b.dataset.quick;$('quick-track-title').textContent=quickMode==='weight'?'Enregistrer mon poids':'Enregistrer mes mensurations';$('quick-track-date').value=today();$('quick-track-weight').hidden=quickMode!=='weight';$('quick-track-measures').hidden=quickMode!=='measure';$('quick-track-weight-value').value='';document.querySelectorAll('[data-quick-measure]').forEach(input=>input.value='');$('quick-track-error').hidden=true;quickDialog.showModal();}));$('quick-track-cancel').addEventListener('click',()=>quickDialog.close());quickDialog.addEventListener('click',e=>{if(e.target===quickDialog)quickDialog.close();});$('quick-track-form').addEventListener('submit',e=>{e.preventDefault();const date=$('quick-track-date').value,db=read();if(!date)return;const error=msg=>{$('quick-track-error').textContent=msg;$('quick-track-error').hidden=false;};if(quickMode==='weight'){const value=Number($('quick-track-weight-value').value);if(!Number.isFinite(value)||value<=0||value>500)return error('Saisis un poids valide.');db.weights=db.weights||{};db.weights[date]=value;}else{const values=[...document.querySelectorAll('[data-quick-measure]')].filter(input=>input.value.trim()!=='');if(!values.length)return error('Renseigne au moins une mensuration.');if(values.some(input=>!Number.isFinite(Number(input.value))||Number(input.value)<=0||Number(input.value)>300))return error('Vérifie les mesures saisies.');db.measurements=db.measurements||{};db.measurements[date]=db.measurements[date]||{};values.forEach(input=>db.measurements[date][input.dataset.quickMeasure]=Number(input.value));}write(db);quickDialog.close();render();});
for(const id of ['measure','nutrition']){document.querySelectorAll('[data-'+id+'-period]').forEach(b=>b.addEventListener('click',()=>{$(id+'-window').value=b.dataset[id+'Period'];id==='measure'?renderMeasure():renderNutrition();}));$(id+'-history-toggle').addEventListener('click',()=>{const panel=$(id+'-history-panel');panel.hidden=!panel.hidden;$(id+'-history-toggle').setAttribute('aria-expanded',String(!panel.hidden));});} $('nutrition-go-journal').addEventListener('click',()=>document.querySelector('[data-page="journal"]').click());
document.querySelectorAll('[data-weight-period]').forEach(b=>b.addEventListener('click',()=>{$('weight-window').value=b.dataset.weightPeriod;renderWeight();}));$('weight-history-toggle').addEventListener('click',()=>{const panel=$('weight-history-panel');panel.hidden=!panel.hidden;$('weight-history-toggle').setAttribute('aria-expanded',String(!panel.hidden));});
function openTracking(id){document.body.classList.add('inside-tracking');$('tracking-dashboard').hidden=true;$('tracking-detail').hidden=false;for(const panel of ['weight','measure','nutrition'])$('track-'+panel).hidden=panel!==id;render();window.scrollTo(0,0);}
function closeTracking(){document.body.classList.remove('inside-tracking');$('tracking-dashboard').hidden=false;$('tracking-detail').hidden=true;renderOverview();window.scrollTo(0,0);}
$('tracking-back').addEventListener('click',closeTracking);document.querySelectorAll('[data-tracking-open]').forEach(b=>b.addEventListener('click',()=>openTracking(b.dataset.trackingOpen)));
for(const id of ['combine-weight','combine-waist','combine-glutes'])$(id).addEventListener('change',renderMeasure);$('measure-compare-from').addEventListener('change',renderMeasure);$('measure-compare-to').addEventListener('change',renderMeasure);$('measure-kind').addEventListener('change',renderMeasure);$('measure-from').addEventListener('change',renderMeasure);$('measure-to').addEventListener('change',renderMeasure);$('nutrition-window').addEventListener('change',renderNutrition);$('nutrition-from').value=dayOffset(today(),-29);$('nutrition-to').value=today();$('nutrition-from').addEventListener('change',renderNutrition);$('nutrition-to').addEventListener('change',renderNutrition);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const date=b.dataset.deleteWeight;if(date&&confirm('Supprimer cette pesée ?')){const db=read();delete db.weights[date];write(db);render();}const m=b.dataset.deleteMeasure;if(m&&confirm('Supprimer cette mesure ?')){const db=read();delete db.measurements[m][$('measure-kind').value];write(db);render();}if(b.dataset.page==='suivi'){closeTracking();render();}});
const DEMO_MARK='gp-demo-2026-11-14';
const demoDates=()=>Array.from({length:9},(_,i)=>dayOffset(today(),-28+i*3+(i===8?4:0)));
function demoRefresh(){const db=read(),present=(db.demoTracking?.dates||[]).length>0;$('demo-tracking-add').hidden=present;$('demo-tracking-remove').hidden=!present;$('demo-tracking-status').textContent=present?'Démonstration active · '+db.demoTracking.dates.length+' relevés fictifs · ouvrir Mensurations pour consulter les courbes':'Aucune donnée fictive active';}
$('demo-tracking-add').addEventListener('click',()=>{
 const db=read();if(db.demoTracking?.dates?.length){openTracking('measure');return;}db.days=db.days||{};
 const dates=demoDates(),weight=[74.5,74.2,74.0,73.7,73.8,73.4,73.1,72.8,72.6],waist=[85,84.5,84,83.8,83.5,83,82.5,82,81.5],hips=[105,104.7,104.3,104,103.7,103.4,103.2,103,102.8],glutes=[108,108.2,108.3,108.5,108.4,108.7,108.9,109,109.2],thigh=[57,56.9,56.8,56.7,56.6,56.5,56.5,56.4,56.3];
 db.weights=db.weights||{};db.measurements=db.measurements||{};
 const originals={weights:{},measurements:{}};
 dates.forEach((d,i)=>{originals.weights[d]=Object.hasOwn(db.weights,d)?db.weights[d]:null;originals.measurements[d]=Object.hasOwn(db.measurements,d)?JSON.parse(JSON.stringify(db.measurements[d])):null;db.weights[d]=weight[i];db.measurements[d]={...(db.measurements[d]||{}),waist:waist[i],hips:hips[i],glutes:glutes[i],thigh:thigh[i],chest:96-i*.1,upperThigh:65-i*.1,arm:29+i*.1};});
 db.demoTracking={marker:DEMO_MARK,dates,originals,inserted:dates.map(d=>({date:d,weight:db.weights[d],measurements:JSON.parse(JSON.stringify(db.measurements[d]))}))};
 write(db);render();demoRefresh();openTracking('measure');
});
$('demo-tracking-remove').addEventListener('click',()=>{
 const db=read(),demo=db.demoTracking;if(demo?.marker!==DEMO_MARK)return;
 for(const entry of demo.inserted||[]){const d=entry.date;if(db.weights?.[d]===entry.weight){if(demo.originals.weights[d]===null)delete db.weights[d];else db.weights[d]=demo.originals.weights[d];}
 if(JSON.stringify(db.measurements?.[d])===JSON.stringify(entry.measurements)){if(demo.originals.measurements[d]===null)delete db.measurements[d];else db.measurements[d]=demo.originals.measurements[d];}}
 delete db.demoTracking;write(db);render();demoRefresh();
});
demoRefresh();
window.addEventListener('storage',render);render();
})();